'use strict';
let scorePreset='government';
const scoringMeta=()=>DATA.scoring;
const currentPreset=()=>scoringMeta().presets[0];
const scoreValue=r=>NannyScoring.score(r);
const selectionOf=r=>r.officialSelection||{};
const scoreGroupKey=r=>selectionOf(r).group==='official'&&selectionOf(r).identityGate!=='pass'?'identity':selectionOf(r).group||'business';
const scoreGroupNames={official:'2025 劳务品牌名录优先组',historical:'其他政府记录（非当期质量认定）',supplement:'补充机构',identity:'品牌与法人关联待核',business:'北京育儿业务待核',platform:'平台入口'};
const scoreGroupOrder=Object.fromEntries(NannyScoring.groups.map((group,index)=>[group,index]));
const scoreGroup=r=>selectionOf(r).groupLabel||scoreGroupNames[scoreGroupKey(r)]||'资料待核实';
const scoreNumber=n=>Number.isFinite(Number(n))?String(Number(Number(n).toFixed(2))):'0';
const scoreState=level=>level===0?'未取得适用的正向加分依据':level===1?'有限或历史线索':'有具体公开资料，仍需核本单';
function scoreGate(r){const s=selectionOf(r),group=scoreGroupKey(r);if(s.identityGate==='hold')return '<span class="score-gate">先核清品牌与签约法人关联</span>';if(group==='official')return '<span class="score-gate score-gate-pass">以入选法人签约为前提</span>';return `<span class="score-gate">${group==='platform'?'按具体店铺和签约主体核实':group==='historical'?'政府记录有年份与适用范围限制':group==='business'?'先确认北京育儿业务与接单':'未列入名录优先组，不等于服务差'}</span>`;}
function scoreRankText(r,ranks){const rank=ranks[r.id];return scoreGroupKey(r)==='official'&&rank?`手册组内${rank.tied?'并列 ':''}第 ${rank.position} 名`:'不参与优先组排名';}
function scoreBadge(r){const s=scoreValue(r),government=Number(s.components[0])||0;return `<span class="score-badge"><b>${scoreNumber(s.total)}</b><span>/ 100</span></span><span class="table-sub score-split">政府 ${scoreNumber(government)} ＋ 保障 ${scoreNumber(Number(s.total)-government)}</span>${scoreGate(r)}`;}
function scoreGrid(r){const s=scoreValue(r),weights=currentPreset().weights;return `<div class="score-component-grid">${scoringMeta().dimensions.map((d,i)=>{const points=Number(s.components[i])||0,percent=weights[i]?Math.max(0,Math.min(100,points/weights[i]*100)):0;return `<div class="${i===0?'government-component':''}"><span>${esc(d.name)}</span><b>${scoreNumber(points)}<small> / ${weights[i]}</small></b><span class="score-mini-track" aria-hidden="true"><i style="width:${percent}%"></i></span></div>`;}).join('')}</div>`;}
function officialSummary(r,compact=false){
 const s=selectionOf(r),matches=s.matches||[];
 if(compact){const m=matches.find(x=>x.recordType==='labor-brand-2025')||matches[0];return `<div class="official-summary official-summary-compact"><span class="official-group-label">2025 年劳务品牌推选</span><p>${esc(m?.listedCompany||'完整法人见政府来源')}</p>${m?.matchStatus==='brand-linked'?'<p class="official-identity">品牌与名录法人已有来源关联；仅适用于该法人合同。</p>':''}${m?.url?`<a class="source-link" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">核对政府原文 ↗</a>`:''}</div>`;}
 return `<div class="official-summary ${scoreGroupKey(r)==='official'?'official-summary-selected':''}"><span class="official-group-label">${esc(scoreGroup(r))}</span><p>${esc(s.summary||'政府记录及适用范围待补充核实。')}</p>${s.identityReason?`<p class="official-identity"><strong>主体关联：</strong>${esc(s.identityReason)}</p>`:''}${s.businessGate==='hold'&&s.businessReason?`<p class="official-identity"><strong>育儿业务：</strong>${esc(s.businessReason)}</p>`:''}${matches.length?`<span class="micro">${matches.length} 条政府来源记录 · 取最高分，不叠加</span>`:''}</div>`;
}
function officialSourceFor(id){return (scoringMeta().officialSources||[]).find(s=>s.id===id||s.sourceId===id)||{};}
function officialField(v){if(v===null||v===undefined||v==='')return '来源未注明，见原文';if(Array.isArray(v))return v.map(officialField).join('；');if(typeof v==='object')return v.label||v.text||v.description||[v.from||v.start,v.to||v.end].filter(Boolean).join(' 至 ')||'有效范围见来源原文';return String(v);}
function officialMatchCard(match){const source=officialSourceFor(match.sourceId),url=match.url||source.url,title=match.title||source.title||'政府来源原文',status=match.matchStatus;const statusLabel=({exact:'法人名称一致',confirmed:'关联已核对',brand:'品牌关联已核对','brand-linked':'品牌与法人关联已核对',matched:'已匹配',pass:'关联已核对',hold:'关联待核实',pending:'关联待核实',unmatched:'关联未核清'})[status]||status||'关联情况见下方';return `<article class="official-source-card"><div class="official-source-top"><span class="tag ${['hold','pending','unmatched'].includes(status)?'amber':'blue'}">${esc(statusLabel)}</span><span class="official-source-points">该记录 ${scoreNumber(match.points??source.points)} 分</span></div><h4>${esc(match.listedCompany||source.listedCompany||'完整法人名称见原始名录')}</h4><dl class="official-source-facts"><dt>年份</dt><dd>${esc(officialField(match.year??source.year))}</dd><dt>性质</dt><dd>${esc(officialField(match.nature??source.nature))}</dd><dt>有效范围</dt><dd>${esc(officialField(match.validity??source.validity))}</dd><dt>品牌关联</dt><dd>${esc(match.matchBasis||'请核对本次合同完整法人，与名录所列主体是否一致。')}</dd></dl>${url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`:'<p class="micro">该记录未附直接来源链接，需补充原始页面。</p>'}</article>`;}
function governmentBreakdown(r){const s=selectionOf(r),points=scoreValue(r).components[0],matches=s.matches||[];return `<article class="government-reason"><div class="score-reason-heading"><h4>政府入选依据</h4><b>${scoreNumber(points)} / 60 分</b></div>${officialSummary(r)}<p class="score-criterion"><strong>计分方式：</strong>2025 年劳务品牌名录 60 分；已过有效期的 2024 年员工制记录 15 分；2023 年历史记录、2025 年劳务输入基地记录各 10 分。只取可适用记录的最高值，不叠加。其他政府记录不进入2025 年名录优先组。</p>${matches.length?`<div class="official-source-list">${matches.map(officialMatchCard).join('')}</div>`:'<div class="official-source-empty">未取得可归属的政府入选记录。其余保障资料仍单独评分，缺少入选依据不等于服务差。</div>'}<p class="official-contract-note">名录关联限于所列法人。品牌下其他公司、加盟门店及平台商户不自动承接入选身份；联系时须核对合同、收款、派工与售后主体。</p></article>`;}
function guaranteeReason(r,d,i){const s=scoreValue(r),level=r.scorecard.levels[i],sources=(r.scorecard.sourceRefs?.[i]||[]).map(ref=>({ref,source:r.research?.sources?.[Number(String(ref).replace(/^s/i,''))-1]})).filter(x=>x.source);return `<article><div class="score-reason-heading"><h4>${esc(d.name)}</h4><b>${scoreNumber(s.components[i])} / ${currentPreset().weights[i]} 分</b></div><p class="score-level">${esc(level)} / 5 档 · ${scoreState(level)}</p><p>${esc(r.scorecard.reasons[i]||'未取得该项适用的公开依据。')}</p>${d.levels?.[level]?`<p class="score-criterion"><strong>所用标准：</strong>${esc(d.levels[level])}</p>`:''}<div>${sources.length?sources.map(({ref,source})=>`<a class="source-link" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(String(ref).toUpperCase())} · ${esc(source.title)} ↗</a><span class="micro">${esc(source.type||'公开资料')} · ${esc(source.readStatus||'读取边界见档案')}</span>`).join(''):'<p class="micro">本轮未取得可用于该项加分的直接来源；完整检索记录保留在档案下方。</p>'}</div></article>`;}
function scoreBreakdown(r){const m=scoringMeta();return `<section class="score-detail" aria-label="${esc(r.name)}评分依据"><div class="score-detail-heading"><div><p class="eyebrow">政府依据与保障资料参考分</p>${scoreBadge(r)}</div><div><strong>政府依据 60% ＋ 五项保障 40%</strong><p>资料截至 ${esc(m.evidenceAsOf)} · 模型 v${esc(m.version)}<br>${esc(scoreGroup(r))}</p></div></div><p class="score-boundary">先按政府记录与主体关联分组，再看组内保障资料。分数是本手册的比较规则，不是政府评分、服务质量或满意度；缺少政府依据或保障资料不等于服务差。</p>${scoreGrid(r)}<details class="score-reasons" open><summary>政府来源与完整法人</summary>${governmentBreakdown(r)}</details><details class="score-reasons"><summary>展开其余五项保障的打分理由与来源 · 共 40 分</summary>${m.dimensions.slice(1).map((d,i)=>guaranteeReason(r,d,i+1)).join('')}</details></section>`;}
function officialSourceDirectory(){const sources=scoringMeta().officialSources||[];return `<details class="method official-source-directory"><summary>核对政府原始来源与完整名录 · ${sources.length} 项</summary><p>不同来源的认定对象、年份和有效期分别保留。名录不是政府给育儿嫂机构的服务质量排名，也不说明当前有可上户人选。</p>${sources.map(s=>{const companies=s.companies||[];return `<details class="official-directory-record"><summary>${esc(s.title||s.name||s.id||'政府来源')} · ${companies.length?companies.length+' 个主体':'标准、政策或公示说明 · 不直接加分'}</summary><dl class="official-source-facts"><dt>年份</dt><dd>${esc(officialField(s.year))}</dd><dt>性质</dt><dd>${esc(officialField(s.nature))}</dd><dt>有效范围</dt><dd>${esc(officialField(s.validity))}</dd></dl>${s.url?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开政府来源 ↗</a>`:''}${companies.length?`<ol class="official-company-list">${companies.map(c=>`<li>${esc(typeof c==='string'?c:c.company||c.name||c.entity||c.listedCompany||'法人名称见原文')}</li>`).join('')}</ol>`:'<p class="micro">完整名单请见原始来源。</p>'}</details>`;}).join('')}</details>`;}
function groupDescription(group){return ({official:'仅比较有2025 年劳务品牌名录依据、且品牌与法人关联通过核对的机构。名次是本手册按保障资料形成的组内顺序，不是政府名次；搜索不会重算排名。',historical:'此组含历史员工制记录和劳务输入基地等其他政府记录。年份、有效期与认定性质不同，不视为当前服务质量认定，不进入名录优先组排名。',supplement:'补充机构的公开保障资料可以比较，但不能代替政府入选依据或主体核验。未进入优先组不等于服务差。',identity:'先核清品牌、门店与完整签约法人的关联。即使找到近名政府记录或保障总分较高，也不进入名录优先组。',business:'此组北京育儿业务仍待确认，可能已有政府入选记录，但入选工种与实际服务范围不能直接推定为育儿嫂。先核当前北京育儿业务与接单，再比较分数；不参与优先组排名。',platform:'平台入口按具体订单、店铺和完整签约法人核实。平台品牌不代表每家商户入选，也不承担统一的换人与退费条款。',all:'先显示2025 年名录优先组，再按政府记录性质、主体关联和平台身份分组。任何分项排序都只在组内生效，分数不会把缺少政府依据或主体未核清的条目提升到优先组。'})[group]||'先核政府记录性质与主体，再比较保障资料。';}
function setupScores(){
 const m=scoringMeta(),groups=Object.keys(scoreGroupOrder),official=items.filter(r=>scoreGroupKey(r)==='official').length;
 $('#scores').innerHTML=head('GOVERNMENT EVIDENCE & SAFEGUARDS','先看入选依据，再比较换人保障','政府依据占 60%，换人、退费、筛选、售后与费用共占 40%。先按记录性质和主体关联分组，再看组内顺序。')+
 `<div class="score-overview"><div><b>${official}</b><span>进入2025 年名录优先组</span></div><div><b>60%</b><span>政府依据的固定权重</span></div><div><b>40%</b><span>五项保障资料的权重</span></div></div>
 <div class="government-priority-rule"><div><span class="priority-step-number">1</span><strong>先核来源、法人和业务</strong><p>核对名录法人和北京育儿业务，再区分记录性质。</p></div><div><span class="priority-step-number">2</span><strong>再做组内比较</strong><p>官网保障说明再详细，也不替代政府入选与主体门槛。</p></div><div><span class="priority-step-number">3</span><strong>最后核本单合同</strong><p>名录身份限于完整法人；换人时限与退费仍须逐单确认。</p></div></div>
 <div class="score-notice"><strong>这里的分数和顺序由本手册制定，不是政府评分或服务质量排名。</strong><p>2025 年劳务品牌名录是当前优先组的依据。历史员工制记录、劳务输入基地记录的性质不同，保留较低分值并单独分组。无政府入选依据、主体关联未核清的条目不进入首页优先组。</p><p>缺少依据不等于服务差。政府入选也不证明实际履约；口碑与投诉、当前候选和本次合同必须另看。投诉条数、“未搜到投诉”和单方经历不直接改变分数。</p></div>
 <div class="score-settings score-fixed-weights"><strong>固定权重 · 政府依据 60%，其余保障 40%</strong><p>政府记录取适用最高分，不叠加。其余五项沿用同一套证据档位，并按以下权重换算。</p><div id="score-weights" class="weight-pills">${m.dimensions.map((d,i)=>`<span class="${i===0?'government-weight':''}">${esc(d.name)} <b>${currentPreset().weights[i]}%</b></span>`).join('')}</div></div>
 <details class="method scoring-method"><summary>查看计分规则、组内排名与证据门槛</summary><p><strong>总分 = 政府依据分（最高 60）＋五项保障分（最高 40）。</strong>政府分直接由入选来源、年份、性质与法人关联决定；五项保障分别按“档位 ÷ 5 × 对应权重”换算。</p><div class="government-score-scale"><div><b>60 分</b><span>2025 年劳务品牌名录<br>主体关联通过后进入优先组</span></div><div><b>15 分</b><span>2024 年员工制历史记录<br>一年有效期已过</span></div><div><b>10 分</b><span>2023 年历史记录／2025 年劳务输入基地<br>其他政府记录，不是当期质量认定</span></div><div><b>0 分</b><span>未取得可适用的入选加分依据<br>具体原因见逐家档案</span></div></div><p>上述政府分取最高值，不把多条记录相加。关联未核清的近名主体不能凭名录分数进入优先组。优先组内总分相同则并列，下一名按竞赛排名跳号；其他组显示分数但不标主榜名次。</p><p>五项保障逐项阅读来源判档，不按关键词、搜索顺序或来源数量自动打分。本轮未核本单合同、拟派人员与替补库存，因此没有取得最高 5 档所需的履约证据。0 分可能因为资料缺失，也可能条款未提供正向保障，逐项理由说明区别。</p><p>不同城市、不同工种和近名公司的政策不得移用；仅有旧资料、第三方推广或未读全文摘录只作为有限线索。更低价格不加分，只比较费用是否讲清楚。消费者个例金额不作为当前价目表。</p>${m.dimensions.slice(1).map(d=>`<details class="dimension-rubric"><summary>${esc(d.name)} · ${d.weight} 分</summary><ol start="0">${(d.levels||[]).map((t,i)=>`<li><b>${i} 档</b> ${esc(t)}</li>`).join('')}</ol></details>`).join('')}<p class="micro">资料快照：${esc(m.evidenceAsOf)}；模型 v${esc(m.version)}。权重是本次选择偏好，不是经统计验证的服务预测模型。</p></details>
 ${officialSourceDirectory()}
 <div class="section-heading"><h2>按政府依据分组，逐家查看</h2><a class="source-link" href="scores.csv" download>下载评分与分组 CSV ↓</a></div>
 <div class="filters score-filters"><label class="search-label"><span>搜索机构</span><input id="score-search" type="search" placeholder="机构、主体或区域"></label><label><span>政府依据与主体分组</span><select id="score-group">${groups.filter(g=>items.some(r=>scoreGroupKey(r)===g)).map(g=>`<option value="${g}">${esc(scoreGroupNames[g])} · ${items.filter(r=>scoreGroupKey(r)===g).length}</option>`).join('')}<option value="all">全部条目 · ${items.length}</option></select></label><label><span>机构类型</span><select id="score-category"><option value="all">全部类型</option>${[...new Set(items.map(r=>r.category))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label><span>组内排序</span><select id="score-sort"><option value="total">总参考分从高到低</option><option value="replacement">换人保障从高到低</option><option value="refund">退出退费从高到低</option><option value="vetting">人员筛选从高到低</option><option value="coverage">有依据的维度从多到少</option></select></label></div>
 <div class="results-line"><p id="score-count" role="status" aria-live="polite"></p><button class="text-button" id="score-reset">重置评分筛选</button></div><p class="score-group-explanation" id="score-group-note"></p><div id="score-results"></div>`;
 $('#scores .page-heading').insertAdjacentHTML('beforeend','<button class="outline-button" id="jump-score-list">直接看分组机构 ↓</button>');
 $('#jump-score-list').addEventListener('click',()=>$('#score-results').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 ['score-search','score-group','score-category','score-sort'].forEach(id=>$('#'+id).addEventListener('input',renderScores));
 $('#score-reset').addEventListener('click',()=>{$('#score-search').value='';$('#score-group').value=official?'official':'all';$('#score-category').value='all';$('#score-sort').value='total';renderScores();});
 if(official)$('#score-group').value='official';renderScores();
}
function renderScores(){
 const m=scoringMeta(),ranks=NannyScoring.rank(items),q=$('#score-search').value.trim().toLowerCase(),group=$('#score-group').value,category=$('#score-category').value,sort=$('#score-sort').value;
 const list=items.filter(r=>(group==='all'||scoreGroupKey(r)===group)&&(category==='all'||r.category===category)&&(!q||[r.name,r.entity,r.address,r.contact].join(' ').toLowerCase().includes(q))).sort((a,b)=>{const groupDifference=(scoreGroupOrder[scoreGroupKey(a)]??99)-(scoreGroupOrder[scoreGroupKey(b)]??99);if(groupDifference)return groupDifference;const sa=scoreValue(a),sb=scoreValue(b),index=m.dimensions.findIndex(d=>d.key===sort),specific=sort==='coverage'?sb.covered-sa.covered:index>=0?sb.components[index]-sa.components[index]:0;return specific||NannyScoring.compare(a,b)||a.id.localeCompare(b.id);});
 $('#score-count').textContent=`显示 ${list.length} / ${items.length} 个条目 · 政府 60% ＋ 保障 40%`;$('#score-group-note').textContent=groupDescription(group);let previousGroup='';
 $('#score-results').innerHTML=list.length?list.map(r=>{const key=scoreGroupKey(r),separator=group==='all'&&key!==previousGroup?`<div class="score-group-divider"><h3>${esc(scoreGroupNames[key])}</h3><p>${esc(groupDescription(key))}</p></div>`:'';previousGroup=key;return separator+`<article class="score-row score-row-${key}"><div class="score-row-main"><span class="score-rank">${scoreRankText(r,ranks)}</span><button class="name-button" data-agency="${esc(r.id)}">${esc(name(r.name))}</button><span class="table-sub">${esc(r.category)}</span><div class="score-row-number">${scoreBadge(r)}</div></div><div class="score-row-body">${officialSummary(r)}${scoreGrid(r)}<p class="score-summary">${esc(r.scorecard.serviceSummary||r.scorecard.summary)}</p><details class="score-reputation" open><summary>口碑与履约提示 · 不计入分数</summary><p>${esc(reputationSummary(r))}</p>${r.complaintAudit?'<a class="source-link" href="#complaints">查看投诉与处理、逐家来源 →</a>':''}</details><div class="score-row-bottom">${openButton(r,'看政府原文、法人和五项保障')}<span class="micro">逐项解释依据与缺口</span></div></div></article>`;}).join(''):'<div class="empty">没有符合条件的条目，试试重置筛选。</div>';
}
function renderScoredShortlist(){
 const ranks=NannyScoring.rank(items),ranked=items.filter(r=>NannyScoring.eligible(r)&&selectionOf(r).businessGate==='pass').sort(NannyScoring.compare);
 $('#shortlist-heading').textContent='先联系：2025 年劳务品牌名录中的机构';$('#shortlist-caption').textContent='组内按本手册保障资料排序 · 不是政府名次';
 $('#shortlist-content').innerHTML=ranked.length?ranked.slice(0,4).map(r=>`<article class="agency-card official-shortlist-card"><div class="card-top"><span class="score-rank">${scoreRankText(r,ranks)}</span><span class="tag blue">政府名录 · 主体已关联</span></div><h3>${esc(name(r.name))}</h3><div class="shortlist-score">${scoreBadge(r)}</div>${officialSummary(r,true)}<p>${esc(r.scorecard.serviceSummary||r.scorecard.summary)}</p><div class="review-brief"><span>口碑提示 · 独立于分数</span>${esc(reputationSummary(r))}</div><p class="card-question">${esc(r.question)}</p>${openButton(r,'核对政府来源、法人和换人条款')}</article>`).join(''):'<div class="empty">本轮尚无同时满足 2025 年名录依据、主体关联与北京育儿业务门槛的条目。请在评分页分别查看政府记录与待核事项。</div>';
 $('#shortlist-extra').innerHTML=`<div class="score-notice"><strong>首页先过三道门槛：有 2025 年政府名录依据、品牌能关联到入选法人、北京育儿业务有适用线索。</strong><p>符合门槛的 ${ranked.length} 家再按保障资料形成组内顺序，首页展示前 ${Math.min(4,ranked.length)} 家。政府依据占 60%，五项保障共占 40%；其他政府记录、缺少依据或主体待核条目分别列组，不因官网承诺多而进入优先组。</p><p>入选不是服务质量保证，也不是政府推荐顺序。名录身份限于相应法人合同；未入选或资料缺失不等于服务差。当前候选、到岗时限和退费条款仍须核实。</p></div><div class="platform-callout"><div><p class="eyebrow">GOVERNMENT 60% + SAFEGUARDS 40%</p><h2>看清来源，也看清适用范围</h2><p>${items.length} 个条目均保留分数、分组和理由。政府原文可点击，能核对完整法人、年份、认定性质及有效期；历史员工制和劳务输入基地记录单独查看。</p></div><a class="outline-button" href="#scores">查看全部分组与评分 →</a></div><div class="complaint-home"><strong>投诉与处理继续单独核查</strong><p>黑猫、消费保、12315 官方公示与监管媒体记录，逐家查看处理结果。政府名录和分数不能替代实际履约经历。</p><a class="outline-button" href="#complaints">查看投诉与处理 →</a></div><div class="steps"><article><b>1</b><h3>先核入选法人</h3><p>对照政府原文与完整公司名称，问清合同、收款、派工和售后主体。</p></article><article><b>2</b><h3>再问换人与退费</h3><p>把免费次数、同档差价、到岗期限和匹配失败退出写进本单合同。</p></article><article><b>3</b><h3>核验具体人选</h3><p>检查近期相同月龄经验、体检、背景与照护实操，并确认替补安排。</p></article></div>`;
}
